draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // head
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20 + 10 * Math.sin(2 * t), 0, 2 * Math.PI);
  ctx.fill();

  // body
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20 + 10 * Math.sin(2 * t));
  ctx.lineTo(W/2, H/2 + 100 + 50 * Math.sin(t));

  // arms
  ctx.moveTo(W/2, H/2 + 50 + 20 * Math.sin(2 * t));
  ctx.lineTo(W/2 - 30 + 20 * Math.cos(t), H/2 + 70 + 10 * Math.sin(2 * t));
  ctx.moveTo(W/2, H/2 + 50 + 20 * Math.sin(2 * t));
  ctx.lineTo(W/2 + 30 + 20 * Math.cos(t), H/2 + 70 + 10 * Math.sin(2 * t));

  // legs
  ctx.moveTo(W/2, H/2 + 100 + 50 * Math.sin(t));
  ctx.lineTo(W/2 - 20 + 10 * Math.cos(2 * t), H - 20);
  ctx.moveTo(W/2, H/2 + 100 + 50 * Math.sin(t));
  ctx.lineTo(W/2 + 20 + 10 * Math.cos(2 * t), H - 20);

  ctx.stroke();

  ctx.restore();
}
